mapper.select:
SELECT GROUP_CD, CODE, CODE_NAME, SORT_ORDER, USE_YN
FROM TB_COMMON_CODE
WHERE GROUP_CD = #{groupCd}
	AND CODE = #{code}

mapper.update:
UPDATE TB_COMMON_CODE
SET	CODE_NAME = #{codeName},
	SORT_ORDER = #{sortOrder}
WHERE GROUP_CD = #{groupCd}
	AND CODE = #{code}

UPDATE TB_COMMON_CODE
	SET	USE_YN = #{useYn}
WHERE GROUP_CD = #{groupCd}
	AND CODE = #{code}
